public class DatasetUtilities_iterateDomainBounds_TriageGen1Test {

    @Test
    public void testIterateDomainBounds_NullDatasetThrowsException() {
        assertThrows(IllegalArgumentException.class, () -> {
            DatasetUtilities.iterateDomainBounds(null, false);
        });
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_IncludeIntervalFalse() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        Mockito.when(dataset.getSeriesCount()).thenReturn(1);
        Mockito.when(dataset.getItemCount(0)).thenReturn(2);

        // Item 0: x=1.0
        Mockito.when(dataset.getXValue(0, 0)).thenReturn(1.0);
        // Item 1: x=5.0
        Mockito.when(dataset.getXValue(0, 1)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, false);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_IncludeIntervalTrue() {
        // When includeInterval is true but dataset is NOT IntervalXYDataset, 
        // it should fall into the 'else' block and use getXValue.
        XYDataset dataset = Mockito.mock(XYDataset.class);
        Mockito.when(dataset.getSeriesCount()).thenReturn(1);
        Mockito.when(dataset.getItemCount(0)).thenReturn(1);
        Mockito.when(dataset.getXValue(0, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, true);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeIntervalTrue() {
        IntervalXYDataset dataset = Mockito.mock(IntervalXYDataset.class);
        Mockito.when(dataset.getSeriesCount()).thenReturn(1);
        Mockito.when(dataset.getItemCount(0)).thenReturn(2);

        // Item 0: [1.0, 3.0]
        Mockito.when(dataset.getStartXValue(0, 0)).thenReturn(1.0);
        Mockito.when(dataset.getEndXValue(0, 0)).thenReturn(3.0);
        // Item 1: [4.0, 6.0]
        Mockito.when(dataset.getStartXValue(0, 1)).thenReturn(4.0);
        Mockito.when(dataset.getEndXValue(0, 1)).thenReturn(6.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, true);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(6.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_WithNaNValues() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        Mockito.when(dataset.getSeriesCount()).thenReturn(1);
        Mockito.when(dataset.getItemCount(0)).thenReturn(3);

        // Item 0: NaN
        Mockito.when(dataset.getXValue(0, 0)).thenReturn(Double.NaN);
        // Item 1: 2.0
        Mockito.when(dataset.getXValue(0, 1)).thenReturn(2.0);
        // Item 2: 8.0
        Mockito.when(dataset.getXValue(0, 2)).thenReturn(8.0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, false);

        assertEquals(2.0, result.getLower(), 1e-9);
        assertEquals(8.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_WithNaNValues() {
        IntervalXYDataset dataset = Mockito.mock(IntervalXYDataset.class);
        Mockito.when(dataset.getSeriesCount()).thenReturn(1);
        Mockito.when(dataset.getItemCount(0)).thenReturn(2);

        // Item 0: [NaN, 5.0]
        Mockito.when(dataset.getStartXValue(0, 0)).thenReturn(Double.NaN);
        Mockito.when(dataset.getEndXValue(0, 0)).thenReturn(5.0);
        // Item 1: [2.0, NaN]
        Mockito.when(dataset.getStartXValue(0, 1)).thenReturn(2.0);
        Mockito.when(dataset.getEndXValue(0, 1)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, true);

        assertEquals(2.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_EmptyDatasetReturnsNull() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        Mockito.when(dataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_AllNaNReturnsNull() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        Mockito.when(dataset.getSeriesCount()).thenReturn(1);
        Mockito.when(dataset.getItemCount(0)).thenReturn(1);
        Mockito.when(dataset.getXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(dataset, false);

        assertNull(result);
    }
}
